import java.lang.reflect.Method; public class DebugInfo { public static void main(String[] args) { try { Class<?> cls = Class.forName("vn.payos.service.blocking.v2.paymentRequests.PaymentRequestsService"); for (Method m : cls.getMethods()) { if (m.getName().equals("get")) { System.out.print("get("); for(Class<?> p : m.getParameterTypes()) System.out.print(p.getName() + " "); System.out.println(")"); } } } catch (Exception e) { e.printStackTrace(); } } }
